// ===== USER INPUT =====
// Ensure month and year are parsed as integers
const month = parseInt($input.first().json.headers.month, 10); // 1 = Jan
const year = parseInt($input.first().json.headers.year, 10);

// Safely handle holidays whether passed as an array or a comma-separated string
let holidays = $input.first().json.headers.holidays || [];
if (typeof holidays === 'string') {
  holidays = holidays.split(',').map(h => h.trim());
}
// ======================

// Calculate the number of days in the specific month
const days = new Date(year, month, 0).getDate();

// Get the binary data from the first input item
const binaryData = $input.first().binary;

const output = [];

for (let d = 1; d <= days; d++) {
  // JavaScript months are 0-indexed in the Date constructor (0 = Jan, 11 = Dec)
  const date = new Date(year, month - 1, d);
  const dayOfWeek = date.getDay(); // 0 = Sun, 6 = Sat

  // Format strings with leading zeros
  const dayStr = String(d).padStart(2, '0');
  const monthStr = String(month).padStart(2, '0');

  // Your sheet name format: DD-MM
  const sheetName = `${dayStr}-${monthStr}`;

  // Your holiday format from headers: MM-DD
  const holidayFormat = `${monthStr}-${dayStr}`;

  const isWeekend = (dayOfWeek === 0 || dayOfWeek === 6);

  // Check if the current date is in the holidays array
  // (Checks both MM-DD and DD-MM just in case the input varies)
  const isHoliday = holidays.includes(holidayFormat) || holidays.includes(sheetName);

  // Skip weekends + holidays
  if (isWeekend || isHoliday) {
    continue;
  }

  // Push valid dates to output with the attached binary data
  output.push({
    json: { sheetName: sheetName },
    binary: binaryData
  });
}

return output;

const items = $input.all();
const currentYear = new Date().getFullYear();

const groupedByDate = {};
const result = [];

// Month mapping
const monthNames = [
  "Jan","Feb","Mar","Apr","May","Jun",
  "Jul","Aug","Sep","Oct","Nov","Dec"
];

// 🔹 Normalize DD-MM or DD-MM-YYYY → DD-MM-YYYY
function normalizeDate(rawDate) {
  const parts = rawDate.split("-");

  let dd, mm, yyyy;

  if (parts.length === 2) {
    // Format: DD-MM
    [dd, mm] = parts;
    yyyy = currentYear;
  } 
  else if (parts.length === 3) {
    // Format: DD-MM-YYYY
    [dd, mm, yyyy] = parts;
  } 
  else {
    return null;
  }

  const dateObj = new Date(yyyy, mm - 1, dd);

  const finalDD = String(dateObj.getDate()).padStart(2, "0");
  const finalMM = String(dateObj.getMonth() + 1).padStart(2, "0");
  const finalYYYY = dateObj.getFullYear();

  return `${finalDD}-${finalMM}-${finalYYYY}`;
}

// 🔹 Step 1 — Group records
for (const item of items) {

  const rawDate = item.json.Date;
  if (!rawDate) continue;

  const normalized = normalizeDate(rawDate);
  if (!normalized) continue;

  if (!groupedByDate[normalized]) {
    groupedByDate[normalized] = {
      descriptions: [],
      base: item.json
    };
  }

  if (item.json["Task Description"]) {
    groupedByDate[normalized].descriptions.push(
      item.json["Task Description"]
    );
  }
}

// 🔹 Detect month safely
const firstKey = Object.keys(groupedByDate)[0];
if (!firstKey) {
  return [];
}

const parts = firstKey.split("-");
const month = parseInt(parts[1], 10) - 1;  // second value is month now
const year = parseInt(parts[2], 10);

// 🔹 Build full month
const start = new Date(year, month, 1);
const end = new Date(year, month + 1, 0);

// 🔹 Step 2 — Generate full month data
for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {

  const dd = String(d.getDate()).padStart(2, "0");
  const mm = String(d.getMonth() + 1).padStart(2, "0");
  const yyyy = d.getFullYear();

  const key = `${dd}-${mm}-${yyyy}`;
  const monthName = monthNames[d.getMonth()];
  const day = d.getDay();
  const isWeekend = (day === 0 || day === 6);

  if (groupedByDate[key]) {

    const base = groupedByDate[key].base;

    let comment = base.Comments || "";

    if (isWeekend) {
      comment = "Weekend";
    }

    result.push({
      json: {
        ...base,
        Month: monthName,
        Date: key,
        "Task Start Date": key,
        "Task End Date": key,
        "Task Description": (isWeekend || comment === "Holiday/Leave")
          ? ""
          : groupedByDate[key].descriptions.join("\n"),
        Comments: comment
      }
    });

  } 
  else {

    const comment = isWeekend ? "Weekend" : "Holiday/Leave";

    result.push({
      json: {
        Month: monthName,
        Date: key,
        "Task Start Date": key,
        "Task End Date": key,
        Environment: "Boomi",
        AdminDevSupport: "Support",
        "Task Description": "",
        Complexity: "",
        "Actual Efforts(hrs)": 8,
        Status: "",
        Comments: comment
      }
    });

  }
}

return result;

